import { IValidServerResponse, IValidator } from './types';

export { IValidator } from './types';

export class EndGameValidator<TResponse extends IValidServerResponse> {
    private _items: IValidator<TResponse>[] = [];
    private _currentMessage: TResponse | null;
    private _logger: (message: string) => void;

    public addItemToValidate(item: IValidator<TResponse>): void {
        this._items.push(item);
    }

    public removeValidator(item: IValidator<TResponse>): void {
        const index: number = this._items.indexOf(item);
        if (index !== -1) {
            this._items.splice(index, 1);
        }
    }

    public reset(): void {
        this._items = [];
        this._currentMessage = null;
    }

    public startGame(message: TResponse): void {
        if (this._currentMessage) {
            const currentGameID: number = this._currentMessage.GameMessage.GameId;
            const newGameID: number = message.GameMessage.GameId;
            if (currentGameID !== newGameID) {
                this.log('game already in progress');
            }
        }

        this._currentMessage = JSON.parse(JSON.stringify(message));
    }

    public continueGame(message: TResponse): void {
        if (this._currentMessage) {
            const currentGameID: number = this._currentMessage.GameMessage.GameId;
            const newGameID: number = message.GameMessage.GameId;
            if (currentGameID !== newGameID) {
                this.log('error starting game ' + newGameID + ' game ' + currentGameID + ' already in progress');
            }
        } else {
            this.log('no game in progress');
        }

        this._currentMessage = JSON.parse(JSON.stringify(message));
    }

    public endGame(): void {
        if (this._currentMessage) {
            window.$endGameResponse = this._currentMessage;

            let errorOccured: boolean = false;
            const errorStrings: string[] = [];
            for (const validator of this._items) {
                if (!validator.isValid(this._currentMessage)) {
                    errorOccured = true;
                    const errorString: string = validator.getError(this._currentMessage);
                    let found: boolean = false;
                    for (const error of errorStrings) {
                        if (error === errorString) {
                            found = true;
                        }
                    }
                    if (!found) {
                        errorStrings.push(validator.getError(this._currentMessage));
                    }
                }
            }
            if (errorOccured) {
                let errorString: string = '';
                for (const error of errorStrings) {
                    errorString += error + '\n';
                }
                this.log(errorString);
            }
            this._currentMessage = null;
        }
    }

    public setLogger(logger: (message: string) => void): void {
        this._logger = logger;
    }

    private log(message: string): void {
        if (this._logger !== undefined) {
            const currentGameID = this._currentMessage ? this._currentMessage.GameMessage.GameId : 'unknown-gameId';
            this._logger(`End Game Verification - ${currentGameID} - ${message}`);
        }
    }
}
